package udea.integrador.ingenote.infrastructure.adapter.out.persistence;
import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import udea.integrador.ingenote.domain.model.Valoracion; import udea.integrador.ingenote.domain.port.out.ValoracionPersistencePort; import udea.integrador.ingenote.infrastructure.adapter.out.persistence.entity.ValoracionJpaEntity; import udea.integrador.ingenote.infrastructure.adapter.out.persistence.repository.*; import java.util.*;
@Repository public class ValoracionPersistenceAdapter implements ValoracionPersistencePort {
 private final ValoracionSpringDataRepository votos; private final RecursoSpringDataRepository recursos; private final UsuarioSpringDataRepository usuarios; public ValoracionPersistenceAdapter(ValoracionSpringDataRepository v,RecursoSpringDataRepository r,UsuarioSpringDataRepository u){votos=v;recursos=r;usuarios=u;}
 private Valoracion d(ValoracionJpaEntity e){return new Valoracion(e.getId(),e.getRecurso().getId(),e.getUsuario().getId(),e.getVoto(),e.getFechaCreacion());}
 @Transactional(readOnly=true) public boolean existeRecurso(UUID id){return recursos.existsById(id);} @Transactional(readOnly=true) public Optional<Valoracion> buscarPorRecursoYUsuario(UUID r,UUID u){return votos.findByRecursoIdAndUsuarioId(r,u).map(this::d);}
 @Transactional public Valoracion guardar(Valoracion x){ValoracionJpaEntity e;if(x.id()==null)e=new ValoracionJpaEntity(recursos.getReferenceById(x.recursoId()),usuarios.getReferenceById(x.usuarioId()),x.voto(),x.fechaCreacion());else{e=votos.findById(x.id()).orElseThrow();e.cambiarVoto(x.voto());}return d(votos.save(e));} @Transactional public void eliminar(UUID id){votos.deleteById(id);} @Transactional(readOnly=true) public long puntajeNeto(UUID id){return votos.puntajeNeto(id);}@Transactional(readOnly=true) public long cantidadVotos(UUID id){return votos.countByRecursoId(id);}
}
